-- READ ONLY. Expect 11 business triggers, zero guards, revision 7.1.
USE auxiliares;
SELECT COUNT(*) AS triggers_negocio FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME NOT LIKE 'TRG_71_GUARD_%';
SELECT COUNT(*) AS guardas_pendientes FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME LIKE 'TRG_71_GUARD_%';
SELECT REVISION FROM FB_MODELO_REVISION WHERE MODELO='consultas';
SELECT TIPO_DOCUMENTO,COLUMN_NAME,IS_NULLABLE FROM (SELECT 'CI/RUT unique; OTROS NULL' AS TIPO_DOCUMENTO,COLUMN_NAME,IS_NULLABLE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='FB_PERSONAS' AND COLUMN_NAME='DOCUMENTO_IDENTIDAD_UNICA') x;
